4,49490101,61193644,75139292,44998654,49526208,16752649,81569942,33425729,45041923,49229903,28563253,81406076,42699838,49243809,49244542,54469846,66600964,69033295,64992891,65699801,52732738,49534014,49569363,49494207,47452286,47432163,47356343,42695193,45241892,40165442,12948372,62355243,69291025,32905439,56063973,24561052,49472073,49230233,67589791,50227934,25825018,15069510,68202957,13876745,15234547,37279522,47294104,79376815,80394033,56336201,70601569,80088830,68157448,78617713,79653882,13935227,44018651,67874226,26737173,33006945,23979337,15093298,80843620,67841634,69212883,81714778,56218519,51423471,58516867,77877507,73209943,45359765,43253294,31051440,65396436,19500595,16946244,28024672,66502258,20478060,44312010,12926617,70891510,17133547,49574144,49298708,49478326,63654572,17037701,49468883,4511074,49491538,81759947'
DECLARE @tmpCustId AS TABLE (CustId INT)
DECLARE @tmp_Bettrans AS TABLE(ID [int] IDENTITY (1,1) PRIMARY KEY, Custid INT, sum_stake MONEY, oddsid INT)
DECLARE @StartRow INT 
		, @StopRow INT 
		, @MaxRow INT  -- Keep the total row of your data
		, @Threshold INT  -- the number of each batch
DECLARE @debug_message VARCHAR(500)

INSERT INTO @tmpCustId (CustId)
SELECT DISTINCT value 
FROM string_split (@CustIds, ',')

--Sum stake on active range
INSERT INTO @tmp_Bettrans (Custid, sum_stake, oddsid) --oddsid = 1: soccer, 99: mix sport
SELECT b.custid, ISNULL(SUM(b.stake),0) AS sum_stake, b.oddsid 
FROM bettrans b WITH (NOLOCK)	
	INNER JOIN @tmpCustId t ON t.CustId = b.CustID
WHERE matchid IN (9,29) 
	AND bettype IN (9,29) 
	AND ruben = 0
	AND b.oddsid = 99 -- mix sports parlay
GROUP BY b.custid, b.oddsid

--Insert data for custid who doesn't have ticket on active range (stake = 0)
INSERT INTO @tmp_Bettrans (Custid, sum_stake, oddsid) 
SELECT t.CustId, 0 sum_stake, 99 oddsid -- Mix Sports Parlay
FROM @tmpCustId t 
WHERE NOT EXISTS (SELECT 1 FROM @tmp_Bettrans b WHERE t.CustId = b.Custid)

SET @MaxRow = (SELECT MAX(ID) FROM @tmp_Bettrans)
SET @Threshold = 1000

IF @Threshold >= @MaxRow
	SET @Threshold = @MaxRow

--MBC
--Mix sport; turnover = 0

-- SET for first batch
SELECT @StartRow = 1, @StopRow = @Threshold

WHILE (@MaxRow IS NOT NULL)
BEGIN
	
	PRINT @StartRow
	PRINT @StopRow

	UPDATE l SET l.AccumTurnover = 0, l.AccumPayout = 0				
	FROM CustLimitBet_MBC l WITH (ROWLOCK, UPDLOCK)		
		INNER JOIN @tmp_Bettrans b ON b.Custid = l.CustID AND b.oddsid = 99
	WHERE EventTypeID = 4
		AND matchid = 29 
		AND b.sum_stake = 0
		AND l.AccumTurnover <> 0
		AND b.ID BETWEEN @StartRow AND @StopRow

	SET @debug_message = CONVERT(VARCHAR(50), GETDATE(), 121)			
		RAISERROR (@debug_message, 0, 1) WITH NOWAIT

	IF @StopRow = @MaxRow BREAK

	WAITFOR DELAY '00:00:00.100' --optional

	SET @StartRow = @StopRow + 1
	SET @StopRow = @StopRow + @Threshold
	IF @StopRow >= @MaxRow
	SET @StopRow = @MaxRow
END

-- SET for first batch
SELECT @StartRow = 1, @StopRow = @Threshold

WHILE (@MaxRow IS NOT NULL)
BEGIN
	
	PRINT @StartRow
	PRINT @StopRow

	UPDATE l SET l.AccumTurnover = b.sum_stake, l.AccumPayout = PO_History.sum_payout	
	FROM CustLimitBet_MBC l WITH (ROWLOCK, UPDLOCK)		
		INNER JOIN @tmp_Bettrans b ON b.Custid = l.CustID AND b.oddsid = 99
		CROSS APPLY (
				SELECT SUM(h.PayoutAdjust) AS sum_payout
				FROM CustLimitBetHistory_MBC h WITH (NOLOCK)
					INNER JOIN bettrans b WITH (NOLOCK) ON b.TransId = h.Transid AND b.statusID NOT IN (101)
				WHERE h.CustID = l.CustID
					AND h.Matchid = l.Matchid
					AND h.EventTypeID = l.EventTypeID
			) AS PO_History
	WHERE EventTypeID = 4
		AND matchid = 29 
		AND b.sum_stake <> 0
		AND b.sum_stake <> l.AccumTurnover
		AND b.ID BETWEEN @StartRow AND @StopRow

	SET @debug_message = CONVERT(VARCHAR(50), GETDATE(), 121)			
		RAISERROR (@debug_message, 0, 1) WITH NOWAIT

	IF @StopRow = @MaxRow BREAK

	WAITFOR DELAY '00:00:00.100' --optional

	SET @StartRow = @StopRow + 1
	SET @StopRow = @StopRow + @Threshold
	IF @StopRow >= @MaxRow
		SET @StopRow = @MaxRow
END
									
